use std::sync::Arc;
use tokio::sync::RwLock;


#[derive(Debug, Clone)]
pub struct Record {
    pub id: u64,
    pub data: Vec<u8>,
}


#[derive(Default)]
pub struct Storage {
    inner: Arc<RwLock<Vec<Record>>>,
}


impl Storage {
    pub fn new() -> Self {
        Storage::default()
