class EventBus {
    constructor() {
        this.listeners = new Map();
    }

    on(event, fn) {
        if (!this.listeners.has(event)) this.listeners.set(event, []);
        this.listeners.get(event).push(fn);
    }

    emit(event, ...args) {
        const fns = this.listeners.get(event) || [];
        for (const fn of fns) fn(...args);
    }
}


